{
  "title": "进水与猜疑",
  "synopsis": "广播站突发无声故障，主持人周野焦急催促并怀疑人为破坏，维修员林岚冷静排查确认是接线盒进水导致短路。两人在共同清理中化解猜疑并定下敲铃约定，却意外发现主线老化，维修任务被迫升级。",
  "preview_blurb": "广播站突发无声故障，焦急的主持人与冷静的维修员在狭窄的配电柜前展开排查，一场关于进水与老化的维修拉扯悄然展开。",
  "scenes": [
    {
      "title": "短路疑云",
      "location": "老街广播站配电柜前",
      "dramatic_goal": "展现故障突发时的焦躁与专业排查的冲突，排除人为破坏的可能。",
      "lines": [
        {
          "kind": "sfx",
          "text": "刺耳的电火花“啪”声，伴随重物砸在铁皮配电箱上的闷响。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "哎哟！怎么又没声了？林师傅，这广播到底什么时候能响？街坊们都等着听晚间新闻呢！"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "别催。万用表显示短路，现在推闸会烧设备。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "短路？会不会是老街那帮调皮捣蛋的把线给剪了？我出去看看……"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "站住。看数据。蜂鸣档响了，阻值接近零。不是断路，是进水导致的短路。"
        }
      ]
    },
    {
      "title": "铜绿与和解",
      "location": "广播站外墙接线盒处",
      "dramatic_goal": "通过共同拆解发现进水真相，打破猜疑，建立初步的合作信任。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "进水？这墙上的接线盒密封得好好的，怎么可能进水？我来扒开看看！"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "别动！你不懂走线，触电了算谁的？拿好手电筒，给我打光。"
        },
        {
          "kind": "sfx",
          "text": "螺丝刀拧开接线盒，塑料盖掉落。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "看清楚了。雨水顺着外墙裂缝倒灌，里面全是铜绿。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "嘶……还真是。抱歉啊林师傅，我这也是急糊涂了，还以为有人搞破坏。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "老街的线路老化是通病，密封胶圈早该换了。拿抹布来，先把积水擦干。"
        },
        {
          "kind": "sfx",
          "text": "擦拭水渍的声音。"
        }
      ]
    },
    {
      "title": "悬置的铃声",
      "location": "广播站配电柜前",
      "dramatic_goal": "确立三声铃约定后立刻用技术现实打破预期，留下悬念。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "积水清了。但防水接头彻底报废，备件在总仓，今晚只能做临时绝缘处理。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "临时处理也行！只要明早能出声。林师傅，咱们定个规矩，等彻底修好恢复广播那天，我敲三声墙上的铜铃，给街坊们报个平安，怎么样？"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "随你。把绝缘胶带递给我。"
        },
        {
          "kind": "sfx",
          "text": "剥线钳用力，突然卡住的金属摩擦声。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "怎么了？"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "主线绝缘层也脆化了。主线也得换，今晚弄不完了。"
        }
      ]
    }
  ],
